#include "edits.hpp"
#include <algorithm>
#include <numeric>
#include <stdexcept>

size_t blitz::tools::offset_of(std::string const& text, size_t line, size_t column)
{
	size_t at = 0;
	for (size_t l = 1; (l < line) && (at < text.size()); at++) {
		if (text[at] == '\n') {
			l++;
		} else if (text[at] == '\r') {
			if ((at + 1 < text.size()) && (text[at + 1] == '\n')) {
				at++;
			}
			l++;
		}
	}
	size_t end = at;
	while ((end < text.size()) && (text[end] != '\n') && (text[end] != '\r')) {
		end++;
	}
	return std::min(at + (column > 0 ? column - 1 : 0), end);
}

blitz::tools::edit blitz::tools::make_edit(std::string const& text, size_t bl, size_t bc, size_t el, size_t ec, std::string replacement)
{
	return edit{ offset_of(text, bl, bc), offset_of(text, el, ec), std::move(replacement) };
}

bool blitz::tools::check_edits(std::string const& text, std::vector<edit> const& edits, std::string& error)
{
	std::vector<size_t> order(edits.size());
	std::iota(order.begin(), order.end(), size_t(0));
	std::stable_sort(order.begin(), order.end(), [&](size_t a, size_t b) { return edits[a].begin < edits[b].begin; });
	size_t last_end = 0;
	for (size_t i : order) {
		auto const& e = edits[i];
		if ((e.begin > e.end) || (e.end > text.size())) {
			error = "An edit at byte " + std::to_string(e.begin) + " is outside of the text.";
			return false;
		}
		if (e.begin < last_end) {
			error = "Edits overlap at byte " + std::to_string(e.begin) + ".";
			return false;
		}
		last_end = std::max(last_end, e.end);
	}
	return true;
}

std::string blitz::tools::apply_edits(std::string const& text, std::vector<edit> edits)
{
	std::string error;
	if (!check_edits(text, edits, error)) {
		throw std::runtime_error(error);
	}
	std::stable_sort(edits.begin(), edits.end(), [](edit const& a, edit const& b) { return a.begin < b.begin; });
	std::string out;
	size_t      at = 0;
	for (auto const& e : edits) {
		out.append(text, at, e.begin - at);
		out += e.replacement;
		at = e.end;
	}
	out.append(text, at, std::string::npos);
	return out;
}
